function withTimeout(promise,label='资源载入',ms=12000){let timer;return Promise.race([Promise.resolve(promise),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(`${label} 超时（>${Math.round(ms/1000)}秒）`)),ms)})]).finally(()=>clearTimeout(timer))}
async function fetchJson(url,ms=10000){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),ms);try{const r=await fetch(url,{cache:'no-store',signal:ctrl.signal});if(!r.ok)throw new Error(`${url} 返回 HTTP ${r.status}`);return await r.json()}catch(e){if(e?.name==='AbortError')throw new Error(`${url} 载入超时`);throw e}finally{clearTimeout(timer)}}

