function makeLayout(id,width){
  const p=[],hz=[],coins=[];let x=0,flip=id%2;
  while(x<width){const ground=520+((x/500|0)%3)*55;p.push([x,910,ground,170]);x+=ground; if(x<width){const gap=90+((x+id*37)%70);hz.push([x,1008,gap,72]);x+=gap;const platW=230+((x+id*91)%120);const py=770-(((x/300|0)+id)%3)*65;p.push([x,py,platW,28]);coins.push(x+platW/2);x+=platW+85;flip^=1;}}
  p.push([Math.max(0,width-520),910,520,170]);
  for(let c=420;c<width-250;c+=430+(id%3)*30)coins.push(c);
  return {platforms:p,hazards:hz,coins:[...new Set(coins.map(v=>Math.round(v)))].filter(v=>v<width-180)};
}
