function deepMerge(a,b){for(const k of Object.keys(b||{})){if(a[k]&&typeof a[k]==='object'&&!Array.isArray(a[k])&&b[k]&&typeof b[k]==='object'&&!Array.isArray(b[k]))deepMerge(a[k],b[k]);else a[k]=b[k]}return a}
function ensureCharacterProfilesBase(){saveData.characters=saveData.characters||{};const migrated=deepMerge(baseProfile(),saveData.characters.Yara||saveData.profile||{});saveData.characters.Yara=migrated;for(const p of Object.values(saveData.characters)){if(p){p.equipment=Object.assign(baseProfile().equipment,p.equipment||{});p.stats=Object.assign(baseProfile().stats,p.stats||{});p.pillBonus=Object.assign(baseProfile().pillBonus,p.pillBonus||{})}}saveData.selectedCharacter=saveData.selectedCharacter||'Yara';syncActiveProfile();ECON.ensureSave?.(saveData)}
