function updateProjectiles(dt){for(const pr of game.projectiles){pr.life-=dt;pr.x+=pr.vx*dt;pr.y+=pr.vy*dt;if(pr.owner==='player'){for(const e of game.enemies)if(!e.dead&&overlap(pr,e)){hitEnemyElemental(e,pr.damage,Math.sign(pr.vx),pr.reaction||'hurt_heavy',pr);pr.life=0;break}}else if(!game.player.dead&&overlap(pr,game.player)){damagePlayer(pr.damage,pr.reaction||'hurt_light',Math.sign(pr.vx),pr);pr.life=0}}game.projectiles=game.projectiles.filter(p=>p.life>0&&p.x>-100&&p.x<game.level.width+100&&p.y>-100&&p.y<H+100)}
