function burst(x,y,n,color){n=Math.max(1,Math.round(n*(V4RENDER.particleScale?.()||1)));for(let i=0;i<n;i++){const seed={x,y,vx:rand(-180,180),vy:rand(-240,90),life:rand(.25,.75),r:rand(2,6),color};game.particles.push(V4POOLS.particlePool?.acquire?V4POOLS.particlePool.acquire(seed):seed)}}function updateParticles(dt){const alive=[];for(const q of game.particles){q.life-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=420*dt;if(q.life>0)alive.push(q);else V4POOLS.particlePool?.release?.(q)}game.particles=alive}
function clearLevel(){
  if(game.cleared)return;
  game.cleared=true;V4AUDIO.playSfx?.('clear');const hp=game.player.hp/game.player.maxHp;let stars=1;if(hp>.55)stars++;if(game.time<190&&hp>.35)stars++;
  if(game.dungeonId){
    V39P.clearDungeon?.(saveData,game.dungeonId,stars);const rewards=V39P.grantDungeonReward?.(saveData,game.dungeonId)||[];addExp(90);game.message=`副本完成 · ${rewards.slice(0,2).join(' / ')}`;game.messageTimer=999;writeSave(false);return;
  }
  const lid=Number(game.level.id);saveData.stars[lid]=Math.max(saveData.stars[lid]||0,stars);saveData.unlocked=Math.max(saveData.unlocked,Math.min(20,lid+1));saveData.lastLevel=Math.min(20,lid+1);addExp(75+lid*14);saveData.cultivation.herbs+=8+lid;saveData.cultivation.stones+=18+lid*2;
  const found=V39P.discoverAfterLevel?.(saveData,lid)||[];writeSave(false);game.message=found.length?`通关 · 发现副本入口：${V39P.dungeon(found[0])?.name||found[0]}`:'通关';game.messageTimer=999
}
function drawBackground(){const L=game.level,im=images['bg'+L.id];ctx.fillStyle='#7694ad';ctx.fillRect(0,0,W,H);if(im&&im.complete){const cw=Math.min(im.width,Math.max(W,im.width*.82)),sx=clamp((game.cameraX/(L.width-W||1))*(im.width-cw),0,Math.max(0,im.width-cw));ctx.drawImage(im,sx,0,cw,im.height,0,0,W,H)}const rh=game.roomController?.hud?.();if(L.stageBoss&&rh&&rh.wave>=2){ctx.fillStyle='rgba(72,32,96,.18)';ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(255,220,170,.05)';for(let i=0;i<9;i++)ctx.fillRect(0,90+i*105,W,2)}}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function platformPalette(levelId){const id=Number(levelId)||1;if(id===4)return{top:'#9b6545',mid:'#563c35',edge:'#ff9a52',moss:'rgba(255,154,76,.16)'};if(id===3)return{top:'#c1b49a',mid:'#5f5b55',edge:'#e8dbc0',moss:'rgba(103,140,96,.18)'};if(id===5)return{top:'#e1d7bd',mid:'#7a8790',edge:'#fff1c8',moss:'rgba(173,207,255,.15)'};return{top:'#789768',mid:'#425243',edge:'#a9c98c',moss:'rgba(112,169,91,.26)'}}
function drawTiledImage(im,x,y,w,h,tileW=900){if(!im||!im.complete||!im.naturalWidth)return false;for(let px=x;px<x+w;px+=tileW){const dw=Math.min(tileW,x+w-px);ctx.drawImage(im,0,0,im.naturalWidth*(dw/tileW),im.naturalHeight,px,y,dw,h)}return true}
function drawVisualPlatform(xx,y,w,h,pal){if(window.YaraV81FX?.terrain(ctx,Number(game.level?.id)||1,xx,y,w,h))return;const id=Number(game.level?.id)||1,ground=h>=80,im=images[(ground?'terrainGround_':'terrainPlatform_')+id];ctx.save();if(im&&im.complete&&im.naturalWidth){const dh=ground?210:Math.max(90,Math.min(160,h+90));drawTiledImage(im,xx,y-(ground?18:14),w,dh,ground?1100:650);ctx.restore();return}/* V5.0 fallback visual: collision stays invisible; draw only a slim terrain lip instead of the old giant green block. */const accent=game.level?.accent||pal.edge||'#cbb88a',topH=ground?18:14,bodyH=ground?34:24;const g=ctx.createLinearGradient(0,y-8,0,y+bodyH);g.addColorStop(0,'rgba(224,214,190,.72)');g.addColorStop(.16,accent+'cc');g.addColorStop(.34,'rgba(46,45,45,.62)');g.addColorStop(1,'rgba(16,20,25,.04)');ctx.fillStyle=g;ctx.fillRect(xx,y-8,w,bodyH);ctx.strokeStyle='rgba(255,242,213,.35)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(xx,y-7);ctx.lineTo(xx+w,y-7);ctx.stroke();for(let px=xx+24;px<xx+w;px+=72){ctx.globalAlpha=.16;ctx.fillStyle=accent;ctx.beginPath();ctx.ellipse(px,y+6,28,5,0,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawLevelDecor(){const id=Number(game.level?.id)||1,vis=battleVisuals?.levels?.[String(id)],cam=game.cameraX;if(!vis)return;for(let i=0;i<(vis.decor||[]).length;i++){const d=vis.decor[i],x=d.x-cam;if(x+d.w<-80||x>W+80)continue;if(d.asset){const im=images['terrainDecor_'+id+'_'+i];if(im&&im.complete)ctx.drawImage(im,x,d.y,d.w,d.h);continue}ctx.save();if(d.type==='steps'){for(let n=0;n<7;n++){ctx.fillStyle=n%2?'rgba(112,105,94,.94)':'rgba(151,141,123,.96)';ctx.fillRect(x+n*d.w/14,d.y-n*7,d.w-n*d.w/7,12)}}else if(d.type==='lava_crack'){ctx.globalCompositeOperation='screen';ctx.strokeStyle='#ff6a2d';ctx.shadowColor='#ff9b3d';ctx.shadowBlur=18;ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(x,d.y);for(let q=1;q<=8;q++)ctx.lineTo(x+d.w*q/8,d.y+(q%2?12:-6));ctx.stroke()}else if(d.type==='jade'){const g=ctx.createLinearGradient(x,d.y,x+d.w,d.y);g.addColorStop(0,'rgba(183,225,235,.35)');g.addColorStop(.5,'rgba(255,239,190,.75)');g.addColorStop(1,'rgba(183,225,235,.35)');ctx.fillStyle=g;ctx.fillRect(x,d.y,d.w,d.h);ctx.strokeStyle='rgba(255,246,210,.8)';ctx.strokeRect(x,d.y,d.w,d.h)}ctx.restore()}}
function drawWorld(){const cam=game.cameraX,L=game.level,pal=platformPalette(L.id);for(const [x,y,w,h] of L.platforms){if(x+w<cam-100||x>cam+W+100)continue;drawVisualPlatform(x-cam,y,w,h,pal)}drawLevelDecor();for(const [x,y,w,h] of L.hazards){const xx=x-cam;if(xx+w<0||xx>W)continue;const g=ctx.createLinearGradient(0,y,0,y+h);g.addColorStop(0,L.id===4||L.id===10?'#ffb05a':'#5f4a46');g.addColorStop(.45,L.id===4||L.id===10?'#ec582d':'#2d2728');g.addColorStop(1,'rgba(15,14,16,.35)');ctx.fillStyle=g;ctx.fillRect(xx,y,w,h)}for(const c of game.coins){if(c.taken)continue;const x=c.x-cam,y=c.y+Math.sin(c.phase)*8;ctx.save();ctx.translate(x,y);ctx.fillStyle='#ffcc45';ctx.strokeStyle='#fff2a8';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-c.r*1.4);ctx.lineTo(c.r,0);ctx.lineTo(2,c.r*1.25);ctx.lineTo(-c.r,2);ctx.closePath();ctx.fillStyle='#8de4dd';ctx.strokeStyle='#d8fffa';ctx.fill();ctx.stroke();ctx.restore()}const portalOpen=game.roomController?game.roomController.allCleared():(game.boss&&game.boss.dead),gx=L.width-140-cam;ctx.save();ctx.translate(gx,775);ctx.globalAlpha=portalOpen?1:.32;ctx.strokeStyle=portalOpen?'#ffe4a0':'#70757f';ctx.lineWidth=11;ctx.beginPath();ctx.ellipse(0,75,50,90,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.restore();drawLoot();drawBattleRoomBarriers()}
