function drawPlayer(p,x,y){const anim=currentPlayerAnimation(p),rawElapsed=playerAnimationElapsed(p),clip=V31.animations?.clip(p.characterId||activeCharacterId(),anim),duration=p.action?.total?.()||p.reaction?.duration||p.overrideAnim?.duration,elapsed=duration?rawElapsed/duration*((clip?.frames||1)/Math.max(1,clip?.fps||8)):rawElapsed,dir=p.dir<0?'left':'right',cid=p.characterId||activeCharacterId();ctx.save();if(p.invuln>0&&Math.floor(p.invuln*22)%2===0)ctx.globalAlpha=.46;if(p.hitFlash>0)ctx.filter='brightness(1.8) saturate(.72)';let drawn=actionRuntime?.draw(ctx,cid,anim,dir,elapsed,x+p.w/2-140,y+p.h-280,280,280,{scale:1.0,equipment:activeProfile().equipment,save:saveData});if(!drawn){const im=images['charPortrait_'+cid]||images.portrait;if(im&&im.complete&&im.naturalWidth){ctx.save();ctx.translate(x+p.w/2,y+p.h);if(p.dir<0)ctx.scale(-1,1);ctx.drawImage(im,-120,-340,240,340);ctx.restore()}}ctx.restore()}
