function initRouteMapInteraction(){const scroller=document.getElementById('levelView');const grid=document.getElementById('levelGrid');if(!scroller||!grid||scroller.dataset.routeBound)return;scroller.dataset.routeBound='1';let dragging=false,sx=0,sy=0,sl=0,st=0,target=false;const isMapTarget=t=>!!(t&&grid.contains(t)&&!t.closest('.route-node, .branch-node, button, a'));scroller.addEventListener('pointerdown',e=>{target=isMapTarget(e.target);if(!target)return;dragging=true;sx=e.clientX;sy=e.clientY;sl=scroller.scrollLeft;st=scroller.scrollTop;scroller.classList.add('dragging-map');try{scroller.setPointerCapture(e.pointerId)}catch{}});scroller.addEventListener('pointermove',e=>{if(!dragging)return;scroller.scrollLeft=sl-(e.clientX-sx);scroller.scrollTop=st-(e.clientY-sy)});const end=()=>{dragging=false;scroller.classList.remove('dragging-map')};scroller.addEventListener('pointerup',end);scroller.addEventListener('pointercancel',end);}
function renderLevels(){
  if(window.V43WorldMap){const dungeonMeta=V39P.state?.dungeons?.dungeons||[];window.V43WorldMap.render({save:saveData,dungeons:dungeonMeta,dungeonState:(id)=>V39P.dungeonState?.(saveData,id)||'hidden',startLevel:(id)=>startLevel(Number(id)-1),startDungeon:(id)=>startDungeon(id)}).catch(err=>console.error('[V6.6] world map render failed',err));return;}
  const grid=document.getElementById('levelGrid');if(!grid)return;
  const meta=V39P.state?.mainline?.mainline||[];const nodes=meta.length?meta:Array.from({length:20},(_,i)=>({id:i+1,name:LEVELS[i]?.name||`第${i+1}关`,subtitle:LEVELS[i]?.subtitle||'',playable:i<20,plannedOnly:i>=20,background:LEVELS[i]?.bg||LEVELS[9].bg,recommendedLevel:V38D.level?.(i+1)?.recommendedLevel||1,recommendedPower:V38D.level?.(i+1)?.recommendedPower||0}));
  const size={w:4200,h:2200};
  const raw=[ [460,1900],[880,1735],[1340,1605],[1030,1410],[1600,1285],[2140,1160],[2700,1015],[3270,880],[2900,690],[2440,575],[1950,500],[1470,430],[1000,360],[620,285],[1210,245],[1820,215],[2460,190],[3040,165],[3600,140],[3980,112] ];
  const positions=nodes.map((n,i)=>raw[i]||[400+(i%5)*620,1900-Math.floor(i/5)*420]);
  const pathPts=positions.map(([x,y])=>`${x},${y}`).join(' ');
  grid.innerHTML=`<svg class="route-svg" viewBox="0 0 ${size.w} ${size.h}" preserveAspectRatio="none" aria-hidden="true"><polyline class="glow-path" points="${pathPts}"></polyline><polyline class="main-path" points="${pathPts}"></polyline></svg>`;
  nodes.forEach((l,i)=>{
    const playable=Number(l.id)<=20&&!l.plannedOnly,locked=!playable||Number(l.id)>saveData.unlocked,stars=saveData.stars[l.id]||0,cleared=stars>0,current=playable&&!locked&&!cleared&&(Number(l.id)===Math.min(saveData.unlocked,20));
    const node=document.createElement('button');node.className='route-node'+(locked?' locked':'')+(cleared?' cleared':'')+(current?' current':'')+(l.plannedOnly?' planned':'');node.style.left=positions[i][0]+'px';node.style.top=positions[i][1]+'px';
    node.innerHTML=`<span class="route-orb" style="background-image:url('${l.background||LEVELS[Math.min(i,19)]?.bg||LEVELS[9].bg}')"></span><span class="route-text"><small>${l.plannedOnly?'FUTURE CHAPTER':'MAIN JOURNEY'} · ${String(l.id).padStart(2,'0')}</small><strong>${l.name}</strong><em>${l.subtitle}${l.plannedOnly?' · 规划中':` · 建议 Lv.${l.recommendedLevel} / 战力 ${l.recommendedPower}`}</em><span class="route-stars">${l.plannedOnly?'◇ 已规划':'★'.repeat(stars)+'☆'.repeat(3-stars)}</span></span>`;
    if(!locked&&playable)node.onclick=()=>startLevel(Number(l.id)-1);else node.setAttribute('aria-disabled','true');grid.append(node);
  });
  const dungeonMeta=V39P.state?.dungeons?.dungeons||[];
  dungeonMeta.forEach(d=>{const state=V39P.dungeonState?.(saveData,d.id)||'hidden';if(state==='hidden')return;const idx=Math.max(0,Math.min(nodes.length-1,d.entryAfterLevel-1)),base=positions[idx],dx=base[0]<size.w*0.6?220:-220,dy=base[1]>size.h*0.45?-125:125,el=document.createElement('button');el.className=`branch-node dungeon-${state}`;el.style.left=(base[0]+dx)+'px';el.style.top=(base[1]+dy)+'px';el.innerHTML=`<span class="branch-orb">${state==='cleared'?'✓':'◇'}</span><span><strong>副本 · ${d.name}</strong><span>${state==='cleared'?'已通关 · 可直接进入':`已发现 · ${d.rewardFocus}`}</span></span>`;el.onclick=()=>startDungeon(d.id);grid.append(el)});
  initRouteMapInteraction();
  const scroller=document.getElementById('levelView');if(scroller&&!scroller.dataset.routeCentered){requestAnimationFrame(()=>{scroller.scrollLeft=Math.max(0,(grid.offsetWidth-scroller.clientWidth)*0.08);scroller.scrollTop=Math.max(0,grid.offsetHeight-scroller.clientHeight-260);scroller.dataset.routeCentered='1';});}
}
