function renderCultivation(){const c=saveData.cultivation,r=realmInfo(),next=r.max?r.start+1:r.next,prog=r.max?100:clamp((c.exp-r.start)/(next-r.start)*100,0,100);document.getElementById('realmName').textContent=r.name;document.getElementById('cultExp').textContent=Math.floor(c.exp);document.getElementById('spiritStone').textContent=c.stones;document.getElementById('herbCount').textContent=c.herbs;document.getElementById('muyuCount').textContent=c.muyu;document.getElementById('onlineTime').textContent=fmtTime(c.onlineSeconds);document.getElementById('realmBar').style.setProperty('--v',prog+'%');document.getElementById('realmHint').textContent=r.max?'当前已达本版最高境界。':`距离 ${REALMS[r.idx+1][0]} 还需 ${Math.max(0,next-c.exp|0)} 修为。`;document.getElementById('cultRate').textContent=`+${cultivationRate().toFixed(2)} 修为 / 秒`;document.getElementById('meditateBtn').textContent=c.meditating?'结束闭关':'开始闭关';document.getElementById('pillQi').textContent=c.pills.qi;document.getElementById('pillBody').textContent=c.pills.body;document.getElementById('pillSpirit').textContent=c.pills.spirit}
function craftPill(t){const c=saveData.cultivation,cost=t==='qi'?[30,25]:[45,40];if(c.herbs<cost[0]||c.stones<cost[1])return alert('药材或灵石不足。');c.herbs-=cost[0];c.stones-=cost[1];c.pills[t]++;markDirty();renderCultivation();writeSave(false)}
