window.addEventListener('keydown',e=>{const k=(e.key||'').toLowerCase();if(e.key==='F3'){e.preventDefault();togglePerfPanel();return;}keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k)||e.code==='Space')e.preventDefault();if(!game.running){if(k==='escape'&&!e.repeat){if(window.YaraV83Sanctum?.isOpen()){window.YaraV83Sanctum.close();return;}const current=document.querySelector('.view.active')?.id;if(['economyView','skillTreeView','techniqueView'].includes(current))showView('growthHallView');else if(current!=='menuView')showView('menuView');}return;}if(!e.repeat&&['b','v','n'].includes(k)){openBattlePanel(k==='b'?'inventory':k==='v'?'skills':'shop');return;}if(game.battleOverlay){if((k==='escape'||k==='m')&&!e.repeat){e.preventDefault();resumeBattlePanel();}return;}if(game.paused){if(k==='escape'&&!e.repeat)togglePause();return;}if((k==='k'||k==='arrowup')&&!e.repeat)jump();if(k==='j'&&!e.repeat)queueBasicAttack();if(k==='l'&&!e.repeat)skillL();if(k==='u'&&!e.repeat)skillU();if(k==='i'&&!e.repeat)skillI();if((e.code==='Space'||k===' ')&&!e.repeat)skillSpace();if((k==='p'||k==='escape')&&!e.repeat)togglePause();if(k==='r'&&!e.repeat){if(game.cleared)restartCurrent();else respawn()}if(k==='m'&&!e.repeat){e.preventDefault();openBattlePanel('map')}if(game.cleared&&k==='enter'&&!e.repeat){if(!game.dungeonId&&game.levelIndex<19)startLevel(game.levelIndex+1);else showView('levelView')}});window.addEventListener('keyup',e=>keys[(e.key||'').toLowerCase()]=false);
canvas.addEventListener('click',e=>{if(!game.cleared)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;if(y>H/2+70&&y<H/2+128){if(x>W/2-205&&x<W/2-20){if(!game.dungeonId&&game.levelIndex<19)startLevel(game.levelIndex+1);else showView('levelView')}else if(x>W/2+20&&x<W/2+205)restartCurrent()}});

