const PERF={visible:false,el:null,last:performance.now(),frames:0,fps:0,drawCalls:0,lastUpdate:0};
function perfEstimateDrawCalls(){const visibleEnemies=(game.enemies||[]).filter(e=>!e.removed).length;return 8+visibleEnemies*3+(game.projectiles?.length||0)*2+(game.particles?.length||0)+(game.damageNumbers?.length||0)+(game.loot?.length||0)*2;}
function updatePerfPanel(now=performance.now()){
  if(!PERF.visible)return;PERF.frames++;if(now-PERF.last>=500){PERF.fps=Math.round(PERF.frames*1000/(now-PERF.last));PERF.frames=0;PERF.last=now;const rs=resourceManager?.stats?.()||{};const ps={p:V4POOLS.particlePool?.stats?.(),e:V4POOLS.enemyPool?.stats?.()};const mem=performance.memory?`${(performance.memory.usedJSHeapSize/1048576).toFixed(1)} MB`:'浏览器未提供';PERF.drawCalls=perfEstimateDrawCalls();if(PERF.el)PERF.el.innerHTML=`<b>V7.0 PERF</b><span>FPS ${PERF.fps}</span><span>Draw ~${PERF.drawCalls}</span><span>Images ${rs.images||0}</span><span>Objects E${game.enemies?.length||0}/P${game.particles?.length||0}</span><span>Pools E${ps.e?.created||0}/P${ps.p?.created||0}</span><span>Memory ${mem}</span>`;}}
function togglePerfPanel(force){PERF.el=PERF.el||document.getElementById('v50PerfPanel');PERF.visible=force===undefined?!PERF.visible:!!force;PERF.el?.classList.toggle('hidden',!PERF.visible);if(saveData?.settings)saveData.settings.debugPerformance=PERF.visible;if(PERF.visible){PERF.last=performance.now();PERF.frames=0}markDirty();}

